:root {
  --bg: #1a1a2e;
  --surface: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --card-back: #533483;
  --card-front: #eaeaea;
  --matched: #4ecca3;
  --focus: #f9c74f;
  --radius: 8px;
  --gap: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.game-container {
  width: 100%;
  max-width: 600px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.game-header {
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 8px;
  color: var(--accent);
}

.stats {
  font-size: 1.25rem;
  font-weight: 600;
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
  aspect-ratio: 1;
  width: 100%;
  max-width: 480px;
  margin: 0 auto;
}

.card {
  background: var(--card-back);
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 2rem;
  color: transparent;
  transition: background 0.2s, transform 0.1s, color 0.2s;
  position: relative;
  aspect-ratio: 1;
  width: 100%;
  padding: 0;
  font-family: inherit;
}

.card:hover {
  background: #6a4c9c;
}

.card:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.card:active {
  transform: scale(0.95);
}

.card.flipped {
  background: var(--card-front);
  color: #1a1a2e;
}

.card.matched {
  background: var(--matched);
  color: #1a1a2e;
  cursor: default;
}

.card.matched:hover {
  background: var(--matched);
}

.win-message {
  text-align: center;
  background: var(--surface);
  padding: 24px;
  border-radius: var(--radius);
  font-size: 1.5rem;
  font-weight: 600;
}

.win-message p {
  margin: 4px 0;
}

.hidden {
  display: none;
}

.new-game-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  padding: 16px 32px;
  font-size: 1.25rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  align-self: center;
  transition: background 0.2s, transform 0.1s;
}

.new-game-btn:hover {
  background: #c73e54;
}

.new-game-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.new-game-btn:active {
  transform: scale(0.97);
}

@media (max-width: 400px) {
  :root {
    --gap: 8px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .game-board {
    max-width: 360px;
  }
  .card {
    font-size: 1.5rem;
  }
}

const COLORS = [
  '#e94560', '#f9c74f', '#4ecca3', '#43aa8b',
  '#577590', '#f8961e', '#9b5de5', '#00bbf9'
];

const board = document.getElementById('game-board');
const moveCounter = document.getElementById('move-counter');
const winMessage = document.getElementById('win-message');
const finalMoves = document.getElementById('final-moves');
const newGameBtn = document.getElementById('new-game-btn');

let cards = [];
let flipped = [];
let matchedPairs = 0;
let moves = 0;
let lockBoard = false;

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function createBoard() {
  const deck = [];
  COLORS.forEach((color, index) => {
    deck.push({ color, pairId: index });
    deck.push({ color, pairId: index });
  });
  shuffle(deck);
  return deck;
}

function renderBoard() {
  board.innerHTML = '';
  cards = createBoard();
  cards.forEach((card, index) => {
    const btn = document.createElement('button');
    btn.className = 'card';
    btn.type = 'button';
    btn.dataset.index = index;
    btn.dataset.pairId = card.pairId;
    btn.setAttribute('aria-label', 'Hidden card');
    btn.style.color = 'transparent';
    btn.textContent = '?';
    btn.addEventListener('click', handleCardClick);
    board.appendChild(btn);
  });
}

function handleCardClick(e) {
  const card = e.currentTarget;
  if (lockBoard || card.classList.contains('flipped') || card.classList.contains('matched')) return;

  card.classList.add('flipped');
  card.style.color = card.dataset.color || 'transparent';
  card.textContent = '★';
  card.setAttribute('aria-label', 'Flipped card');
  flipped.push(card);

  if (flipped.length === 2) {
    moves++;
    moveCounter.textContent = `Moves: ${moves}`;
    checkMatch();
  }
}

function checkMatch() {
  lockBoard = true;
  const [a, b] = flipped;
  if (a.dataset.pairId === b.dataset.pairId) {
    a.classList.add('matched');
    b.classList.add('matched');
    a.setAttribute('aria-label', 'Matched card');
    b.setAttribute('aria-label', 'Matched card');
    matchedPairs++;
    flipped = [];
    lockBoard = false;
    if (matchedPairs === COLORS.length) {
      showWin();
    }
  } else {
    setTimeout(() => {
      a.classList.remove('flipped');
      b.classList.remove('flipped');
      a.style.color = 'transparent';
      b.style.color = 'transparent';
      a.textContent = '?';
      b.textContent = '?';
      a.setAttribute('aria-label', 'Hidden card');
      b.setAttribute('aria-label', 'Hidden card');
      flipped = [];
      lockBoard = false;
    }, 800);
  }
}

function showWin() {
  finalMoves.textContent = moves;
  winMessage.classList.remove('hidden');
}

function resetGame() {
  flipped = [];
  matchedPairs = 0;
  moves = 0;
  lockBoard = false;
  moveCounter.textContent = 'Moves: 0';
  winMessage.classList.add('hidden');
  renderBoard();
}

newGameBtn.addEventListener('click', resetGame);

renderBoard();
